export interface OfflineMedicineRecord {
  name: string;
  aliases: string[];
  genericName: string;
  commonUses: string;
  warnings: string;
  sideEffects: string[];
  estimatedPrice: string;
  philHealthCovered: boolean;
  howToTake?: string;
  avoidWith?: string[];
  importantNotes?: string[];
  missedDoseAdvice?: string;
  whenToSeekHelp?: string;
  storage?: string;
}

// This JSON is generated by scripts/kaggle_to_offline_json.py.
// Keep this file present (can be an empty array) so bundling remains stable.
// Load lazily to avoid blocking app startup with 4.6 MB JSON

let GENERATED_OFFLINE_MEDICINES: OfflineMedicineRecord[] | null = null;
let PHILIPPINE_OFFLINE_MEDICINES: OfflineMedicineRecord[] | null = null;
let PHILIPPINE_GENERATED_OFFLINE_MEDICINES: OfflineMedicineRecord[] | null =
  null;
let ALL_OFFLINE_MEDICINES_CACHE: OfflineMedicineRecord[] | null = null;

type OfflineMedicineDetails = Pick<
  OfflineMedicineRecord,
  | "howToTake"
  | "avoidWith"
  | "importantNotes"
  | "missedDoseAdvice"
  | "whenToSeekHelp"
  | "storage"
>;

function normMedicineKey(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s+-]/g, " ")
    .replace(/\s+/g, " ");
}

