function mergeUniqueStrings(primary: string[] = [], secondary: string[] = []) {
  const seen = new Set<string>();
  const merged: string[] = [];

  for (const value of [...primary, ...secondary]) {
    const cleaned = value?.trim();
    if (!cleaned) continue;
    const key = cleaned.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(cleaned);
  }

  return merged;
}

function enrichOfflineMedicine(
  medicine: OfflineMedicineRecord,
): OfflineMedicineRecord {
  const detailKeys = [medicine.name, medicine.genericName, ...medicine.aliases]
    .map(normMedicineKey)
    .filter(Boolean);

  const details = detailKeys
    .map((key) => OFFLINE_MEDICINE_DETAILS[key])
    .find(Boolean);

  if (!details) {
    return medicine;
  }

  return {
    ...medicine,
    ...details,
    avoidWith: mergeUniqueStrings(details.avoidWith, medicine.avoidWith),
    importantNotes: mergeUniqueStrings(
      details.importantNotes,
      medicine.importantNotes,
    ),
  };
}

function loadGeneratedMedicines(): OfflineMedicineRecord[] {
  if (GENERATED_OFFLINE_MEDICINES === null) {
    try {
      GENERATED_OFFLINE_MEDICINES =
        (
          require("../assets/data/offline-medicines.generated.json") as OfflineMedicineRecord[]
        ).map(enrichOfflineMedicine);
    } catch (error) {
      console.warn("Failed to load offline medicines from JSON:", error);
      GENERATED_OFFLINE_MEDICINES = [];
    }
  }
  return GENERATED_OFFLINE_MEDICINES;
}

function loadPhilippineMedicines(): OfflineMedicineRecord[] {
  if (PHILIPPINE_OFFLINE_MEDICINES === null) {
    try {
      PHILIPPINE_OFFLINE_MEDICINES =
        (
          require("../assets/data/offline-medicines.philippines.json") as OfflineMedicineRecord[]
        ).map(enrichOfflineMedicine);
    } catch (error) {
      console.warn("Failed to load Philippine offline medicines JSON:", error);
      PHILIPPINE_OFFLINE_MEDICINES = [];
    }
  }
  return PHILIPPINE_OFFLINE_MEDICINES;
}

function loadGeneratedPhilippineMedicines(): OfflineMedicineRecord[] {
  if (PHILIPPINE_GENERATED_OFFLINE_MEDICINES === null) {
    try {
      PHILIPPINE_GENERATED_OFFLINE_MEDICINES =
        (
          require("../assets/data/offline-medicines.ph.generated.json") as OfflineMedicineRecord[]
        ).map(enrichOfflineMedicine);
    } catch (error) {
      console.warn(
        "Failed to load generated Philippine offline medicines JSON:",
        error,
      );
      PHILIPPINE_GENERATED_OFFLINE_MEDICINES = [];
    }
  }
  return PHILIPPINE_GENERATED_OFFLINE_MEDICINES;
}

function loadAllOfflineMedicines(): OfflineMedicineRecord[] {
  if (ALL_OFFLINE_MEDICINES_CACHE === null) {
    ALL_OFFLINE_MEDICINES_CACHE = [
      ...OFFLINE_MEDICINES,
      ...loadPhilippineMedicines(),
      ...loadGeneratedPhilippineMedicines(),
      ...loadGeneratedMedicines(),
    ];
  }

  return ALL_OFFLINE_MEDICINES_CACHE;
}

