export const ALL_OFFLINE_MEDICINES: OfflineMedicineRecord[] = OFFLINE_MEDICINES;

export function getOfflineMedicineCount(): number {
  return (
    OFFLINE_MEDICINES.length +
    getPhilippineOfflineMedicineCount() +
    getGeneratedPhilippineOfflineMedicineCount() +
    getGeneratedOfflineMedicineCount()
  );
}

export function getGeneratedOfflineMedicineCount(): number {
  return loadGeneratedMedicines().length;
}

export function getPhilippineOfflineMedicineCount(): number {
  return loadPhilippineMedicines().length;
}

export function getGeneratedPhilippineOfflineMedicineCount(): number {
  return loadGeneratedPhilippineMedicines().length;
}

export function getAllOfflineMedicines(): OfflineMedicineRecord[] {
  return loadAllOfflineMedicines();
}
